"""Render existing diagnostic CSVs into a standalone offline regime explorer.

No data acquisition, scoring, fitting, inference, or hypothesis selection.
"""
from __future__ import annotations

import argparse
import csv
import hashlib
import io
import json
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DEFAULT = ROOT / "outputs/mlb-v18-empirical-diagnosis-v1"


def csv_records(path: Path, allow_partial: bool):
    if not path.exists():
        if allow_partial:
            return [], {"path": str(path), "status": "NOT_YET_AVAILABLE"}
        raise FileNotFoundError(f"Diagnostic CSV is not ready: {path}; use --allow-partial for an explicit partial viewer")
    raw = path.read_bytes()
    records = list(csv.DictReader(io.StringIO(raw.decode("utf-8-sig"))))
    return records, {"path": str(path.resolve()), "sha256": hashlib.sha256(raw).hexdigest(), "bytes": len(raw), "rows": len(records), "status": "AVAILABLE"}


